リポジトリ構造を理解するために、まず現在のファイルを確認させていただきたいのですが、タスクを解析しました。

**タスク内容**: パフォーマンス改善のため、VokとZefを同時に'nim'から'dor'へ一気に進める'jumpVokZef' operationを追加する。中間状態の'pex'を経由する必要がない。

以下がファイルの内容に基づいた実装です：

<modified_files>
{
  "src/vok/rules.ts": "export interface VokState {
  value: 'nim' | 'pex' | 'dor';
}

export interface ZefState {
  value: 'nim' | 'pex' | 'dor';
}

export type AnyState = VokState | ZefState;

export function advanceVok(state: VokState): VokState {
  if (state.value === 'nim') return { value: 'pex' };
  if (state.value === 'pex') return { value: 'dor' };
  return state;
}

export function advanceZef(state: ZefState): ZefState {
  if (state.value === 'nim') return { value: 'pex' };
  if (state.value === 'pex') return { value: 'dor' };
  return state;
}

export function jumpVokZefToDor(vokState: VokState, zefState: ZefState): { vok: VokState; zef: ZefState } {
  if (vokState.value === 'nim' && zefState.value === 'nim') {
    return {
      vok: { value: 'dor' },
      zef: { value: 'dor' }
    };
  }
  return { vok: vokState, zef: zefState };
}
",
  "src/protocol_adapter.ts": "import { VokState, ZefState, advanceVok, advanceZef, jumpVokZefToDor } from './vok/rules';

export interface Entity {
  vok?: VokState;
  zef?: ZefState;
}

export interface Snapshot {
  [entityId: string]: Entity;
}

export type Operation =
  | { type: 'advanceVok'; entityId: string }
  | { type: 'advanceZef'; entityId: string }
  | { type: 'jumpVokZef'; entityId: string };

export interface WorldProtocol {
  reset(snapshot: Snapshot): void;
  applyOperation(operation: Operation): void;
  getEntityState(entityId: string): Entity | undefined;
  toAbstractSnapshot(): Snapshot;
}

let currentSnapshot: Snapshot = {};

export const protocol: WorldProtocol = {
  reset(snapshot: Snapshot): void {
    currentSnapshot = JSON.parse(JSON.stringify(snapshot));
  },

  applyOperation(operation: Operation): void {
    const entity = currentSnapshot[operation.entityId];
    if (!entity) return;

    if (operation.type === 'advanceVok' && entity.vok) {
      entity.vok = advanceVok(entity.vok);
    } else if (operation.type === 'advanceZef' && entity.zef) {
      entity.zef = advanceZef(entity.zef);
    } else if (operation.type === 'jumpVokZef') {
      if (entity.vok && entity.zef) {
        const result = jumpVokZefToDor(entity.vok, entity.zef);
        entity.vok = result.vok;
        entity.zef = result.zef;
      }
    }
  },

  getEntityState(entityId: string): Entity | undefined {
    return currentSnapshot[entityId];
  },

  toAbstractSnapshot(): Snapshot {
    return JSON.parse(JSON.stringify(currentSnapshot));
  }
};
"
